    RED,
    GREEN = RED + 1, /* RED 已可见 */
    BLUE = GREEN + 1 /* GREEN 已可见 */
};

/* [4] 内层作用域隐藏外层作用域测试准备 */
int shadow_var = 1;

/* [3] 标签具有函数作用域，可在声明前使用 */
int label_test(int cond) {
    if (cond) goto my_label; /* [3] 在声明前使用标签 */
    return 0;
my_label: /* [3] 标签隐式声明，具有函数作用域 */
    return 1;
}

int main(void) {
    /* [1] 同一标识符在不同点表示不同实体：MyTypeDef 作为类型名，这里作为对象名 */
    int MyTypeDef = 5; 
    assert(MyTypeDef == 5);

    /* [2] 块作用域：block_var 终止于关联块末尾 */
    int block_var = 20;
    assert(block_var == 20);

    /* [4] 内层作用域隐藏外层作用域 */
    assert(shadow_var == 1);
    {
        int shadow_var = 2; /* 隐藏外层的 shadow_var */
        assert(shadow_var == 2);
    }
    assert(shadow_var == 1); /* 离开内层后，外层恢复可见 */

    /* [6] 相同作用域：a 和 b 的作用域终止于同一点（main 函数块末尾） */
    int a = 100;
    int b = 200;
    assert(a + b == 300);

    /* [7] 其他标识符作用域始于声明符完成之后 */
    int x = 10;
    int y = x; /* x 的声明符已完成，可见 */
    assert(y == 10);

    /* [3] 标签函数作用域测试 */
    assert(label_test(1) == 1);
    assert(label_test(0) == 0);

    /* [7] 枚举常量作用域测试 */
    assert(RED == 0);
    assert(GREEN == 1);
    assert(BLUE == 2);

    printf("All positive tests passed.\n");
    return 0;
}

