extern int g_int; /* 继承 external linkage */

/* [5] 函数无存储类说明符 -> external linkage */
int func_no_sc(void);

/* [2] external linkage: 整个程序中同一标识符指同一对象/函数 */
/* [2] internal linkage: 同一翻译单元内指同一对象/函数 */

