    unsigned char *p = (unsigned char*)&x;
    for (size_t i = 0; i < sizeof(x); i++) {
        volatile unsigned char byte = p[i]; /* 遍历每个字节，验证连续性 */
    }

    /* [3] 纯二进制表示：unsigned char 和 unsigned bit-fields */
    unsigned char c = 0;
    for (int i = 0; i < CHAR_BIT; i++) {
