    /* [8] 多个对象表示不影响结果，不生成陷阱表示 */
    /* +0.0 和 -0.0 有不同表示，但加 1.0 结果相同 */
    assert(pos_zero + 1.0 == neg_zero + 1.0);

    printf("All positive tests passed.\n");

