    assert(sizeof(str) == 6);   /* 含 '\0' */
    assert(strcmp(str, "hello") == 0);

    /* [3] 字符串字面量在其他语境下转换为指针 */
    const char *sp2 = "world";
    assert(sp2[0] == 'w');

    /* [3] 多维数组：第一维转换为指针 */
    int mat[2][3] = { {1,2,3}, {4,5,6} };
    int (*pm)[3] = mat;     /* mat 转换为 &mat[0]，类型 int(*)[3] */
    assert(pm[0][0] == 1);
    assert(pm[1][2] == 6);

    /* ---------- [4] 函数指示符到函数指针转换 ---------- */

    /* [4] 函数指示符转换为函数指针 */
    int (*fp)(int, int) = add;
