    assert(target == 88);

    /* Footnote 54：sizeof 的操作数不发生函数指示符转换，
     * 因此 sizeof(add) 违反 6.5.3.4 约束（见负向测试）。 */

    /* ---------- 无原型函数调用的默认实参提升（配合 6.5.2.2） ---------- */

    /* 无原型函数：实参经默认提升后传递 */
    int r1 = no_proto_int();
