    /* ---------- 返回结构体的函数：f().x 不是 lvalue ---------- */

    /* f().x 是成员访问结果，但 f() 不是 lvalue，故 f().x 不是 lvalue */
    int val = make_point(3, 4).x;   /* 读取 OK */
