    struct S s = {42, 3.14};
    return s;
}

/* 无原型函数，测试默认实参提升 */
int np_func() {
    va_list ap;
    va_start(ap, 0); /* C99 允许无原型函数使用 va_start，但不检查参数名 */
    int i = va_arg(ap, int);       /* char 提升为 int */
    double d = va_arg(ap, double); /* float 提升为 double */
    va_end(ap);
    return i + (int)d;
}

/* 省略号函数，测试省略号后停止转换 */
int ellipsis_func(int fixed, ...) {
    va_list ap;
    va_start(ap, fixed);
    int i = va_arg(ap, int);
    va_end(ap);
    return fixed + i;
}

