int main(void) {
    int a = 10;
    int *p;
    size_t sz;

    /* [1] postfix-expression 作为 unary-expression */
    a;

    /* [1] ++ unary-expression */
    ++a;
    assert(a == 11);

    /* [1] -- unary-expression */
    --a;
    assert(a == 10);

    /* [1] unary-operator cast-expression: & */
    p = &a;
    assert(*p == 10);

    /* [1] unary-operator cast-expression: * */
    *p = 20;
    assert(a == 20);

    /* [1] unary-operator cast-expression: + */
    a = +a;
