    a = -a;
    assert(a == -20);

    /* [1] unary-operator cast-expression: ~ */
    a = ~a;
    assert(a == ~(-20));

    /* [1] unary-operator cast-expression: ! */
    a = !a;
    assert(a == 0);

    /* [1] sizeof unary-expression */
    sz = sizeof a;
    assert(sz == sizeof(int));

    /* [1] sizeof ( type-name ) */
