    int i = 3;
    double d = 2.5;
    /* i 被转换为 double 3.0，结果为 7.5 */
    assert(i * d == 7.5);
    /* i 被转换为 double 3.0，结果为 1.2 */
    assert(i / d == 1.2);

    /* [4] 语义：* 运算符的结果是操作数的乘积 */
    assert(5 * 6 == 30);
    assert(2.5 * 4.0 == 10.0);
    assert(-3 * 7 == -21);

    /* [5] 语义：/ 的结果是商，% 的结果是余数 */
    assert(17 / 5 == 3);
    assert(17 % 5 == 2);
    assert(17.0 / 5.0 == 3.4);
    /* 注：第二操作数为零是未定义行为(UB)，不属于约束，故不测试 */

