    assert(-7 / 2 == -3);
    assert(-7 % 2 == -1);
    assert((-7 / 2) * 2 + (-7) % 2 == -7);

    /* 正数 / 负数：商向零截断为 -3 */
    assert(7 / -2 == -3);
    assert(7 % -2 == 1);
    assert((7 / -2) * (-2) + 7 % (-2) == 7);

    /* 负数 / 负数：商向零截断为 3 */
    assert(-7 / -2 == 3);
    assert(-7 % -2 == -1);
    assert((-7 / -2) * (-2) + (-7) % (-2) == -7);

    printf("All positive tests passed.\n");
    return 0;
}

