        /* P 指向 one-past-the-end 时，((Q)+1)-(P) == 0 */
        int *Q = &arr[9];
        int *P = Q + 1;           /* one-past-the-end */
        assert(((Q + 1) - P) == 0);
        assert(((Q + 1) - P) == ((Q - P) + 1));
        assert(((Q + 1) - P) == -((P - (Q + 1))));
    }

    /* [9] ptrdiff_t 为有符号类型：可表示负值 */
    {
        int arr[5];
        assert((&arr[3] - &arr[0]) > 0);
        assert((&arr[0] - &arr[3]) < 0);
    }

    /* [10] EXAMPLE：VLA 指针运算 */
    {
        int n = 4, m = 3;
        int a[n][m];
        int (*p)[m] = a;          /* p == &a[0] */
        p += 1;                   /* p == &a[1] */
        (*p)[2] = 99;             /* a[1][2] == 99 */
        assert(a[1][2] == 99);
        n = (int)(p - a);         /* n == 1 */
        assert(n == 1);
    }

    /* [11] 若上例数组改为已知常量大小，结果相同 */
    {
        int a[4][3];
        int (*p)[3] = a;
        p += 1;
        (*p)[2] = 99;
        assert(a[1][2] == 99);
        int n = (int)(p - a);
        assert(n == 1);
    }

    printf("All positive tests passed.\n");
    return 0;
}

