    assert((1 << 2 << 1) == 8);   /* (1 << 2) << 1 == 4 << 1 == 8 */
    assert((16 >> 2 >> 1) == 2);  /* (16 >> 2) >> 1 == 4 >> 1 == 2 */

    /* [2] 约束：操作数为整数类型 */
    unsigned int u_val = 10u;
    int i_val = 10;
    long l_val = 10L;
