/* [7] 地址常量 ± 整数常量表达式 */
static int global_arr[10];
static int *init_addr_plus = &global_arr[0] + 5;         /* 地址常量 + 整数常量表达式 */
static int *init_addr_minus = &global_arr[9] - 3;

