/* ========== 正向测试：以下代码应能编译并运行通过 ========== */

/* [4] 相同作用域和相同标签声明同一类型；类型在定义的右大括号前是不完整的，之后是完整的 */
struct S { int a; };
struct S; /* 不重新声明标签，指定同一类型，此时类型已完整 */
void test_scope_and_completeness(void) {
    struct S s1 = {10};
    assert(s1.a == 10);
    assert(sizeof(struct S) == sizeof(int)); /* 类型已完整，可以求大小 */
}

/* [5] 不同作用域或不同标签声明不同的类型；无标签声明不同的类型 */
