/* [5] 示例 2：类型兼容性测试 */
typedef struct s1 { int x; } t1, *tp1;
typedef struct s2 { int x; } t2, *tp2;
void test_example_2() {
    t1 var1 = {1};
    struct s1 var2 = {2};
    /* t1 和 struct s1 是兼容类型 */
    var1 = var2;
    assert(var1.x == 2);

    tp1 ptr1 = &var1;
    struct s1 *ptr2 = &var2;
    ptr1 = ptr2; /* tp1 和 struct s1* 是兼容类型 */
    assert(ptr1->x == 2);
