/* [13] EXAMPLE 1: 原型形式，extern 是存储类说明符，int 是类型说明符 */
extern int max_proto(int a, int b) {
    return a > b ? a : b;
}

/* [13] EXAMPLE 1: 标识符列表形式，int a, b; 是声明列表 */
extern int max_idlist(a, b)
    int a, b;
{
